package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalContextsTest {
 static final List<String> IDS=List.of(DecimalMeasureStories.ADD,DecimalMeasureStories.SUB,DecimalMeasureGroups.MUL,DecimalMeasureGroups.DIV,DecimalTwoStepStories.REMAIN,DecimalTwoStepStories.SHARE);
 static Question q(String id,String x,String y,int count,String unit){
  if(DecimalTwoStepStories.supports(id))return new Question(id,DecimalTwoStepStories.prompt(id,x,y,count,unit),"private expression","private answer");
  if(DecimalMeasureStories.supports(id)){Question old=DecimalMeasureStories.make(id,"1.0","0.0",unit);return new Question(id,old.prompt.replace("1.0",x).replace("0.0",y),"private expression","private answer");}
  Question old=DecimalMeasureGroups.make(id,"1.0",1,unit);return new Question(id,old.prompt.replace("1.0",x).replace("1개",count+"개").replace("1조각",count+"조각").replace("1병",count+"병").replace("1봉지",count+"봉지"),"private expression","private answer");
 }
 static void equalGuides(StudyGuide old,StudyGuide visible){assertEquals(old.teachingVersion,visible.teachingVersion);assertEquals(old.transfer,visible.transfer);assertEquals(old.resultNumeratorFrame,visible.resultNumeratorFrame);assertEquals(old.resultDenominatorFrame,visible.resultDenominatorFrame);assertEquals(old.frames.size(),visible.frames.size());for(int i=0;i<old.frames.size();i++){var a=old.frames.get(i);var b=visible.frames.get(i);assertEquals(a.instruction,b.instruction);assertEquals(a.before,b.before);assertEquals(a.after,b.after);assertEquals(a.expected,b.expected);assertEquals(a.inputFormat,b.inputFormat);assertEquals(a.options,b.options);assertEquals(a.acceptedChoices,b.acceptedChoices);}}
 @Test public void SixPublicOperationsUseRawQuantitiesUnitsCountsAndIgnorePrivateValues(){
  Checker c=new Checker();List<String> values=List.of("201.001","199.999","601.5","401/6","600.999","201001/3000");
  for(String unit:List.of("m","L","kg"))for(int i=0;i<IDS.size();i++){Question q=q(IDS.get(i),"200.500","0.501",3,unit);q.answers=null;q.expression="999=999";q.kind="complexRoots";q.studyGuide=new StudyGuide().step("private","","","999");var saved=q.studyGuide;var g=PublicDecimalContexts.readGeneral(q);assertNotNull(g);assertEquals("200.500",g.firstRaw());assertEquals(unit,g.unit());assertEquals(PublicDecimalContexts.numericInput(values.get(i)),g.value());assertTrue(c.check(q,List.of(),List.of(values.get(i))).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of("999")).status);assertSame(saved,q.studyGuide);assertNull(q.answers);assertEquals("999=999",q.expression);assertEquals("complexRoots",q.kind);assertNotNull(HelpPlan.forQuestion(q));}
  Question raw=q(DecimalTwoStepStories.SHARE,"0.50","0.250",6,"kg");assertEquals("0.50",PublicDecimalContexts.twoStepGivens(raw).first());assertEquals("0.250",PublicDecimalContexts.twoStepGivens(raw).second());assertEquals(6,PublicDecimalContexts.twoStepGivens(raw).groups());assertEquals("200.500",PublicDecimalContexts.measureGivens(q(IDS.get(0),"200.500","0.001",1,"m")).first());assertEquals(999999937,PublicDecimalContexts.groupGivens(q(IDS.get(2),"1.000","0",999999937,"L")).groups());
 }
 @Test public void PublicSyntaxSemanticsAndFinalRepresentationNeverUseStoredFallback(){
  Checker c=new Checker();Question valid=q(DecimalMeasureStories.ADD,"0.50","0.0",1,"m");
  for(String first:List.of("1000000000.0","1.2345","-1.0","1e2","1/2")){Question bad=q(DecimalMeasureStories.ADD,first,"0.0",1,"m");bad.studyGuide=valid.studyGuide;assertNull(PublicDecimalContexts.readGeneral(bad));assertNull(HelpPlan.forQuestion(bad));assertFalse(CurriculumLimits.NONE.allows(bad));assertEquals(Checker.Status.INPUT_NEEDED,c.check(bad,List.of(),List.of("0.5")).status);}
  for(Question bad:List.of(q(DecimalMeasureStories.SUB,"0.1","0.2",1,"m"),q(DecimalTwoStepStories.REMAIN,"0.1","0.5",2,"kg"),q(DecimalMeasureGroups.DIV,"1.0","0",0,"L"),new Question(valid.skillId,valid.prompt.replace("0.0 m","0.0 kg"),"0.5","0.5"))){assertNull(PublicDecimalContexts.readGeneral(bad));assertNull(HelpPlan.forQuestion(bad));}
  valid.answerFormat="decimalValue";assertTrue(c.check(valid,List.of(),List.of("0.500")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(valid,List.of(),List.of("1/2")).status);assertFalse(FractionInput.available(valid));valid.answerFormat="decimal";assertEquals(Checker.Status.INPUT_NEEDED,c.check(valid,List.of(),List.of("0")).status);valid.answerFormat="fraction";assertTrue(c.check(valid,List.of(),List.of("1/2")).correct());assertTrue(FractionInput.defaultFraction(valid));valid.answerFormat="";assertTrue(FractionInput.available(valid));assertFalse(FractionInput.defaultFraction(valid));
  for(String input:List.of("9".repeat(121),"1e2","0.25+0.25","0.5 m","1/0"))assertEquals(Checker.Status.INPUT_NEEDED,c.check(valid,List.of(),List.of(input)).status);
  assertNull(PublicDecimalContexts.numericInput("9".repeat(156)));assertNull(PublicDecimalContexts.readGeneral(null));
 }
 @Test public void ExistingGuideFramesVersionsAndDraftsStayReadOnlyAndReferencesUseOnlyCheckedEntries(){
  List<Question> old=new ArrayList<>();for(String id:List.of(DecimalMeasureStories.ADD,DecimalMeasureStories.SUB))old.add(DecimalMeasureStories.make(id,"1.005","0.09","kg"));old.add(DecimalMeasureGroups.make(DecimalMeasureGroups.MUL,"1.005",3,"m"));for(int k:List.of(2,3))old.add(DecimalMeasureGroups.make(DecimalMeasureGroups.DIV,"1.005",k,"L"));old.add(DecimalTwoStepStories.make(DecimalTwoStepStories.REMAIN,"1.005","0.09",3,"kg"));for(int k:List.of(2,7))old.add(DecimalTwoStepStories.make(DecimalTwoStepStories.SHARE,"1.005","0.09",k,"m"));
  for(Question q:old){var stored=q.studyGuide;equalGuides(stored,PublicDecimalContexts.guide(q));HelpPlan h=HelpPlan.forQuestion(q);assertSame(stored,q.studyGuide);assertFalse(h.canTransfer());assertEquals(stored.frames.size(),h.size());var draft=h.restore(null,q.id);assertEquals(stored.teachingVersion,draft.teachingVersion);assertTrue(draft.entries.stream().allMatch(String::isEmpty));for(int i=0;i<h.size();i++){String value=stored.frames.get(i).expected;assertTrue(h.step(i).accepts(value));while(draft.entries.size()<=i)draft.entries.add("");draft.entries.set(i,value);}draft.stage=h.size();draft.entries.add("");assertNotNull(h.enteredAnswer(draft));var restored=h.restore(draft.copy(),q.id);assertEquals(draft.entries,restored.entries);assertEquals(h.size(),restored.stage);}
  Question q=q(DecimalMeasureStories.ADD,"200.500","0.501",1,"kg");List<String> entries=new ArrayList<>(List.of("add","0200.500","0.501","3","1000","200500","501","201001","201.001"));assertEquals(Map.of("첫째 양 x = ","0200.500","둘째 양 y = ","0.501"),PublicDecimalContexts.references(q,3,entries));entries.set(1,"999");assertEquals(Map.of("둘째 양 y = ","0.501"),PublicDecimalContexts.references(q,3,entries));assertTrue(PublicDecimalContexts.references(q,3,List.of()).isEmpty());assertTrue(PublicDecimalContexts.references(q,0,entries).isEmpty());assertFalse(HelpPlan.forQuestion(q).step(0).accepts("sub"));
 }
 @Test public void BigIntegerCountsAndLongFiniteOutputsRemainReachableWithoutSharedExpressionExpansion(){
  Question nonterm=q(DecimalTwoStepStories.SHARE,"999999999.999","0.001",999999937,"kg");Rational expected=new Rational(new BigInteger("1000000000"),new BigInteger("999999937"));assertEquals(expected,PublicDecimalContexts.value(nonterm));StudyGuide guide=PublicDecimalContexts.guide(nonterm);assertEquals(12,guide.frames.size());assertEquals("999999937000",guide.frames.get(8).expected);HelpPlan h=HelpPlan.forQuestion(nonterm);var draft=h.restore(null,nonterm.id);for(int i=0;i<h.size();i++){while(draft.entries.size()<=i)draft.entries.add("");draft.entries.set(i,guide.frames.get(i).expected);assertTrue(h.step(i).accepts(draft.entries.get(i)));}draft.stage=h.size();assertEquals(expected.toString(),h.enteredAnswer(draft));assertTrue(new Checker().check(nonterm,List.of(),List.of(expected.toString())).correct());assertTrue(FractionInput.defaultFraction(nonterm));assertEquals(1,FractionInput.errorPart(nonterm,"1000000001/999999937"));assertEquals(0,FractionInput.errorPart(nonterm,"1/2"));
  Question finite=q(DecimalTwoStepStories.SHARE,"1.000","0.000",536870912,"L");String decimal=new BigDecimal("1").divide(new BigDecimal("536870912")).toPlainString();assertTrue(new BigDecimal(decimal).scale()>12);assertEquals(6,HelpPlan.forQuestion(finite).size());assertTrue(HelpPlan.forQuestion(finite).step(5).accepts(decimal));assertTrue(new Checker().check(finite,List.of(),List.of(decimal)).correct());try{Expression.number(decimal);fail("Shared twelve-place expression guard changed");}catch(IllegalArgumentException expectedGuard){}
 }
 @Test public void MentalWrittenAndLegacyOptionalWorkRetainTheirActualPermissionsAndPublicAnchor(){
  Question q=q(DecimalMeasureStories.ADD,"1.2","0.3",1,"m");q.expression="999";q.kind="complexRoots";Checker c=new Checker();List<String> wrong=List.of("9+9=18");List<Checker.StepKind> full=List.of(Checker.StepKind.FULL);q.calculationMethod="written";assertTrue(c.check(q,List.of(),List.of("1.5"),List.of()).correct());assertTrue(c.check(q,List.of("1.2+0.3=1.5"),List.of("1.5"),full).correct());assertTrue(c.check(q,List.of("1+1=2"),List.of("1.5"),List.of(Checker.StepKind.PARTIAL)).correct());assertTrue(c.check(q,List.of("1+1=2"),List.of("1.5"),List.of()).correct());assertEquals(Checker.InputTarget.WORK,c.check(q,wrong,List.of("1.5"),full).inputTarget);assertEquals(Checker.Status.WRONG_STEP,c.check(q,wrong,List.of("1.5"),full).status);
  q.calculationMethod="mental";assertTrue(c.check(q,wrong,List.of("1.5"),full).correct());assertTrue(c.check(q,List.of("1+1=3"),List.of("1.5"),List.of(Checker.StepKind.PARTIAL)).correct());assertFalse(c.checkSteps(q,wrong,full).correct());assertEquals("mental",q.calculationMethod);q.calculationMethod=null;assertFalse(c.check(q,wrong,List.of("1.5"),full).correct());q.stepSupport=false;assertEquals(Checker.Status.INPUT_NEEDED,c.checkSteps(q,List.of("1.2+0.3=1.5"),full).status);assertTrue(c.check(q,List.of(),List.of("1.5")).correct());assertFalse(q.stepSupport);
 }
 @Test public void ExplicitUseAsAnswerExtractsOnlyTheStudentsDeclaredFullCandidateDespitePrivateCardinality(){
  Question q=q(DecimalMeasureStories.ADD,"1.2","0.3",1,"m");q.expression="99";q.kind="complexRoots";List<String> steps=List.of("1.2+0.3=1.500");List<Checker.StepKind> full=List.of(Checker.StepKind.FULL);for(String[] answers:Arrays.<String[]>asList(null,new String[0],new String[]{"private"},new String[]{"1","2"})){q.answers=answers;assertEquals("1.500",WorkAnswer.writtenAnswer(q,steps,full));assertEquals(List.of("1.500"),WorkAnswer.writtenAnswers(q,steps,full));assertSame(answers,q.answers);assertEquals("99",q.expression);assertTrue(q.stepSupport);}
  assertTrue(WorkAnswer.writtenAnswers(q,steps,List.of(Checker.StepKind.PARTIAL)).isEmpty());assertTrue(WorkAnswer.writtenAnswers(q,List.of("9+9=18"),full).isEmpty());assertTrue(WorkAnswer.writtenAnswers(q,List.of(),List.of()).isEmpty());q.stepSupport=false;assertTrue(WorkAnswer.writtenAnswers(q,steps,full).isEmpty());assertFalse(q.stepSupport);
 }
}
